ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
   "InvokeEJBURevChainOut": {
      "response": {
         "system": vars.responseRevchain.system ,
         "operation": vars.responseRevchain.operation,
         "result": vars.responseRevchain.result,
         "faults": vars.responseRevchain.faults
      }
   }
}

%dw 2.0
output application/java
---
{
   "Output": {
      "DocTypeId":  
        if(isBlank(payload.resp01.VALOR_HOMOLOGADO) or isEmpty(payload.resp01.VALOR_HOMOLOGADO)) p('docTypeId-default')
            else payload.resp01.VALOR_HOMOLOGADO,
      "DocTypeName": 
        if(isBlank(payload.resp02.VALOR_HOMOLOGADO) or isEmpty(payload.resp02.VALOR_HOMOLOGADO)) p('docTypeName-default')
            else payload.resp02.VALOR_HOMOLOGADO
   }
}

%dw 2.0
output application/json
---
{
   "InvokeEJBURevChainOut": {
      "response": {
         "system": payload.system ,
         "operation": payload.operation,
         "result": payload.result,
         "faults": {
            "subscriber_id": payload.faults.subscriber_id,
            "account_id": vars.map.CreateSystemsAccountsBody.Customer.AccountIdentificationID,
            "plan_impuestos": {
               "type_name": vars.responseRevchain.faults.subscriber_data.tax_plan_data.type_name,
               "tax_plan_vendor": vars.responseRevchain.faults.subscriber_data.tax_plan_data.tax_plan_vendor,
            },
            "ciclo_facturacion": vars.responseRevchain.faults.subscriber_data.billing_entity_id,
            "fault_detail": payload.faults.fault_detail
         }
      }
   }
}
